package unverified;

import metadata.BehavioralDifference;
import metadata.DifferenceType;

import org.junit.jupiter.api.Test;

import java.util.ArrayList;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;

class ClonePair63DifferenceFindingTest {

    private final ClonePair63 subject = new ClonePair63();

    /**
     * Generated by Claude Code (Claude Fable 5.1).
     * Difference type: return_value.
     * Difference manifestation: the methods return different values.
     */
    @Test
    @BehavioralDifference(DifferenceType.RETURN_VALUE)
    void methodsDisagreeWhenTheFirstElementIsEmpty() {
        // method1 inserts the separator before every element but the first,
        // whereas method2 inserts it only when the buffer is already non-empty.
        List<String> elements = new ArrayList<>(List.of("", "a"));

        assertEquals(",a", subject.method1(elements, ","));
        assertEquals("a", subject.method2(elements, ","));
    }
}
